using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class NewGameWorkTests
{
    static ContractWorld New(bool on=true,string selected="person:shingen")=>NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],selected,20261022,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,null,LocalInspectionFindings.Policy,on?NewGameWork.Policy:null);
    static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
    static EntityId Work(WorldSession s,bool accept=true,string id="request:work-cycle"){Assert.Equal(ResultCode.Accepted,s.Submit(NewGameWorld.LocalWork(s.DiagnosticSnapshot(),id),s.Revision).Code);At(s,s.Seconds+1);var t=s.DiagnosticSnapshot().Tasks.Last();var m=s.GetActorView(s.PlayerControl).Messages.Single(m=>m.Id==new EntityId("message:task/"+t.Id.Value.Split(':')[1]+"/order"));Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);if(t.Kind==TaskKind.VoluntaryRequest)Assert.Equal(ResultCode.Accepted,s.Assent(t.Id,s.PlayerControl,accept,s.Revision).Code);return t.Id;}
    static EntityId Notice(WorldSession s)=>AssessmentNotice.Inbox(s,s.PlayerControl).Last().Message;
    static void Open(WorldSession s)=>Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,Notice(s),s.Revision).Code);
    static CommandResult Pay(WorldSession s,EntityId t,string id="work-payment:first")=>s.CollectWorkPayment(new(id),t,s.PlayerControl,s.Revision);
    [Fact]public void OldProfileKeepsNoWalletAndNoAutomaticReply(){var s=new WorldSession(New(false));Work(s);At(s,10);Assert.Empty(AssessmentNotice.Inbox(s,s.PlayerControl));Assert.Null(s.DiagnosticSnapshot().WorkCycle);Assert.Empty(s.DiagnosticSnapshot().ResourceLots);}
    [Fact]public void InitialPrivateMoneyIsDeclaredAndConserved(){var w=New();Assert.All(w.ResourceLots,l=>{Assert.Equal("money",l.Kind);Assert.Equal(l.Owner,l.Holder);Assert.Equal(l.Owner,l.MobileHolder);Assert.Equal(1000,l.InitialQuantity);Assert.Equal(1000,l.Quantity);});Assert.Equal(w.Characters.Count(c=>c.Life==LifeState.Adult),w.ResourceLots.Length);Assert.Empty(w.Units);}
    [Fact]public void CompletionIsNotPersonalReceiptOrPayment(){var s=new WorldSession(New());var t=Work(s);At(s,5);Assert.Empty(AssessmentNotice.Inbox(s,s.PlayerControl));Assert.False(NewGameWork.CanRequest(s,t));Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Empty(s.DiagnosticSnapshot().Transfers);}
    [Fact]public void AssessorReadsOnlyDeliveredOriginalPapers(){var s=new WorldSession(New());var t=Work(s);At(s,5);Assert.DoesNotContain(s.DiagnosticSnapshot().Messaging.Messages,m=>m.Kind==AssessmentNotice.Kind);At(s,6);var w=s.DiagnosticSnapshot();var notice=w.Messaging.Messages.Single(m=>m.Kind==AssessmentNotice.Kind);var payload=ContractJson.Read<AssessmentNotice.Payload>(System.Text.Encoding.UTF8.GetBytes(notice.Body));Assert.Equal(6,notice.CreatedAt);Assert.True(payload.Review.Evidence.Length>=2);Assert.All(payload.Review.Evidence,id=>Assert.Contains(w.Messaging.Knowledge,k=>k.MessageId==id.Value&&k.CharacterId==payload.Assessor.Value&&k.LearnedAt<=6));}
    [Fact]public void SealedReplyHidesResultAndPaymentUntilOpened(){var s=new WorldSession(New());var t=Work(s);At(s,7);Assert.Null(AssessmentNotice.Inbox(s,s.PlayerControl).Single().Known);Assert.False(NewGameWork.CanRequest(s,t));Assert.Equal(ResultCode.NotAvailable,Pay(s,t).Code);Open(s);Assert.True(NewGameWork.CanRequest(s,t));Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));}
    [Fact]public void ActualPaymentMovesExistingMoneyAndSettlesDebt(){var s=new WorldSession(New());var t=Work(s);At(s,7);Open(s);var w=s.DiagnosticSnapshot();var task=w.Tasks.Single(x=>x.Id==t);long total=w.ResourceLots.Sum(l=>l.Quantity);Assert.Equal(20,w.Debts.Single().Outstanding);Assert.Equal(ResultCode.Accepted,Pay(s,t).Code);w=s.DiagnosticSnapshot();Assert.Equal(1020,NewGameWork.Balance(w,s.PlayerControl));Assert.Equal(980,NewGameWork.Balance(w,task.Issuer));Assert.Equal(total,w.ResourceLots.Sum(l=>l.Quantity));Assert.Equal(0,w.Debts.Single().Outstanding);Assert.Single(w.Transfers);}
    [Fact]public void RetryAndNewIdCannotPayTwice(){var s=new WorldSession(New());var t=Work(s);At(s,7);Open(s);Assert.Equal(ResultCode.Accepted,Pay(s,t).Code);string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,Pay(s,t).Code);Assert.Equal(ResultCode.AlreadyAccepted,Pay(s,t,"work-payment:again").Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact]public void OldRevisionCannotPay(){var s=new WorldSession(New());var t=Work(s);At(s,7);Open(s);Assert.Equal(ResultCode.StateChanged,s.CollectWorkPayment(new("work-payment:stale"),t,s.PlayerControl,s.Revision-1).Code);Assert.Empty(s.DiagnosticSnapshot().Transfers);}
    [Fact]public void AnotherPersonCannotCollect(){var s=new WorldSession(New());var t=Work(s);At(s,7);Open(s);Assert.Equal(ResultCode.NotAvailable,s.CollectWorkPayment(new("work-payment:other"),t,new("person:takeda-nobushige"),s.Revision).Code);}
    [Fact]public void RefusalReceivesNoFeeDebt(){var s=new WorldSession(New());var t=Work(s,false);At(s,8);Open(s);Assert.False(NewGameWork.CanRequest(s,t));Assert.Empty(s.DiagnosticSnapshot().Debts);Assert.Equal(ResultCode.NotAvailable,Pay(s,t).Code);}
    [Fact]public void BindingDutyHasNoExtraPrivateFee(){var s=new WorldSession(New(selected:"person:takeda-nobushige"));var t=Work(s);At(s,8);Open(s);Assert.Equal(0,NewGameWork.Reward(s.DiagnosticSnapshot().Tasks.Single(x=>x.Id==t)));Assert.Empty(s.DiagnosticSnapshot().Debts);Assert.Equal(ResultCode.NotAvailable,Pay(s,t).Code);}
    [Fact]public void OwnInspectionCreatesNoPayerOrReply(){var s=new WorldSession(New());Assert.Equal(ResultCode.Accepted,s.Submit(NewGameWorld.Inspect(s.DiagnosticSnapshot(),"request:self-inspect"),s.Revision).Code);At(s,8);Assert.Empty(AssessmentNotice.Inbox(s,s.PlayerControl));Assert.Empty(s.DiagnosticSnapshot().Debts);Assert.Empty(s.DiagnosticSnapshot().Transfers);}
    [Fact]public void AlteredWalletIsRejected(){var w=New();w.ResourceLots=w.ResourceLots.Select((l,i)=>i==0?l with{Quantity=l.Quantity+1}:l).ToArray();Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void RemovingDebtCannotEraseUnpaidWage(){var s=new WorldSession(New());Work(s);At(s,7);var w=s.DiagnosticSnapshot();w.Debts=[];Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void MissingTransferCannotKeepPaidFlag(){var s=new WorldSession(New());var t=Work(s);At(s,7);Open(s);Pay(s,t);var w=s.DiagnosticSnapshot();w.Transfers=[];Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void OpeningMustPrecedePaymentInCommitOrder(){var s=new WorldSession(New());var t=Work(s);At(s,7);Open(s);Pay(s,t);var w=s.DiagnosticSnapshot();w.WorkCycle=w.WorkCycle! with{Openings=w.WorkCycle.Openings.Select(o=>o with{Revision=w.WorkCycle.Payments[0].Revision}).ToArray()};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void EventBudgetCannotPartiallyReadOrPublish(){var s=new WorldSession(New());Work(s);At(s,5);s.SetPaused(false);string before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal("EventBudget",s.AdvanceTo(7,1).StopReason);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact]public void KnownReplyIsReadOnly(){var s=new WorldSession(New());Work(s);At(s,7);Open(s);string before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.NotEmpty(AssessmentNotice.LatestKnown(s,s.PlayerControl));Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact]public void WorkProfileBindsPolicyAndLegacyProfileRemainsUnchanged(){var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"work-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:shingen",20261022,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,null,LocalInspectionFindings.Policy,NewGameWork.Policy);Assert.Equal(NewGameWork.Policy,store.Read(p.Instance).WorkPolicy);Assert.Throws<InvalidDataException>(()=>NewCampaignStore.Build(p with{WorkPolicy=null}));}
    static WorldSession FailedPaper(){var s=new WorldSession(New());Work(s);At(s,5);var w=s.DiagnosticSnapshot();var id=w.Outbox.First(o=>o.Kind=="route-observation").Id;HakutaiKagami.Core.Messaging.MessageFlow.Fail(w.Messaging,id.Value);return new(w);}
    [Fact]public void MissingRoadPaperPreventsReceiptReplyAndFee(){var s=FailedPaper();At(s,10);Assert.Empty(AssessmentNotice.Inbox(s,s.PlayerControl));Assert.Empty(s.DiagnosticSnapshot().Debts);}
    [Fact]public void TimerOnlyLateCopyCannotInventAReceipt(){var s=FailedPaper();At(s,8);var w=s.DiagnosticSnapshot();var a=w.Messaging.Attempts.Single(a=>a.Status==HakutaiKagami.Core.Messaging.AttemptStatus.Lost);HakutaiKagami.Core.Messaging.MessageFlow.ScheduleLate(w.Messaging,a.MessageId,a.Number,8,1);Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void KnownFailedPaperCanBePhysicallyResentToOriginalMeeting(){var s=FailedPaper();At(s,8);var a=s.DiagnosticSnapshot().Messaging.Attempts.Single(a=>a.Status==HakutaiKagami.Core.Messaging.AttemptStatus.Lost);Assert.Equal(ResultCode.Accepted,s.RetryCourier(s.PlayerControl,a.MessageId,"kofu",s.Seconds+1,s.Revision).Code);At(s,11);Assert.Single(AssessmentNotice.Inbox(s,s.PlayerControl));Assert.Single(s.DiagnosticSnapshot().Debts);Assert.Equal(2,s.DiagnosticSnapshot().Messaging.Attempts.Count(x=>x.MessageId==a.MessageId));}
    [Fact]public void LeavingTheMeetingPreventsRemoteCollection(){var s=new WorldSession(New());var t=Work(s);At(s,7);Open(s);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:leave-work","suwa"),s.Revision).Code);At(s,10);Assert.False(NewGameWork.CanRequest(s,t));Assert.Equal(ResultCode.NotAvailable,Pay(s,t).Code);Assert.Equal(20,s.DiagnosticSnapshot().Debts.Single().Outstanding);}
    static void Military(WorldSession s){Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(new(new("request:coins-and-army"),NewMilitaryAction.Request){AuthorityPolicy=NewGameMilitary.AuthorityContract},s.PlayerControl,s.Revision).Code);}
    [Fact]public void MilitarySyncKeepsAlreadyPaidPrivateMoney(){var s=new WorldSession(New());var t=Work(s);At(s,7);Open(s);Assert.Equal(ResultCode.Accepted,Pay(s,t).Code);Military(s);Assert.Equal(1020,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));_ = new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));}
    [Fact]public void PaymentAfterMilitaryRequestSurvivesFullHistoricalReplay(){var s=new WorldSession(New());var t=Work(s);At(s,7);Open(s);Military(s);Assert.Equal(ResultCode.Accepted,Pay(s,t).Code);_ = new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));Assert.Equal(1020,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));}
    [Fact]public void ExhaustedPayerCannotMintCoinsAndDebtRemains(){var s=new WorldSession(New());for(int i=0;i<=50;i++){var t=Work(s,id:"request:many/"+i);At(s,s.Seconds+6);Open(s);Assert.True(NewGameWork.CanRequest(s,t));Assert.Equal(i<50?ResultCode.Accepted:ResultCode.NotAvailable,Pay(s,t,"work-payment:many/"+i).Code);}Assert.Equal(2000,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(20,s.DiagnosticSnapshot().Debts.Sum(d=>d.Outstanding));}
    [Fact]public void UsedPaymentNonceCannotBecomeAWorkRequest(){var s=new WorldSession(New());var t=Work(s);At(s,7);Open(s);Pay(s,t);Assert.Equal(ResultCode.IdPayloadConflict,s.Submit(NewGameWorld.Inspect(s.DiagnosticSnapshot(),"work-payment:first"),s.Revision).Code);}
    [Fact]public void MissingVersionedModuleIsRejected(){var w=New();w.WorkCycle=null;Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void EditedAssessmentCannotInventConfirmedEvidence(){var s=new WorldSession(New());Work(s);At(s,7);var w=s.DiagnosticSnapshot();var m=w.Messaging.Messages.Single(m=>m.Kind==AssessmentNotice.Kind);var p=ContractJson.Read<AssessmentNotice.Payload>(System.Text.Encoding.UTF8.GetBytes(m.Body));w.Messaging.Messages=w.Messaging.Messages.Select(x=>x.Id==m.Id?x with{Body=System.Text.Encoding.UTF8.GetString(ContractJson.Write(p with{Review=p.Review with{Evidence=[]}}))}:x).ToArray();Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    static ContractWorld Island(bool enabled){var a=NewGameWorldTests.Officer("created:island-a",site:"site:iki");var b=NewGameWorldTests.Officer("created:island-b",site:"site:iki");var setup=NewGameWorldTests.Setup([a,b]);return NewGameWorld.Create(setup.World,setup.Registered,a.Id,20261022,NewGameWorld.CompactPersonalAuthority,null,null,LocalInspectionFindings.Policy,enabled?NewGameWork.Policy:null);}
    [Fact]public void UnmappedIslandCannotPromiseAnUnfulfillablePaidInspection(){var w=Island(true);Assert.False(NewGameWork.ScopeSupported(w,new("site:iki")));Assert.Throws<InvalidDataException>(()=>NewGameWorld.LocalWork(w,"request:unmapped-offer"));Assert.Empty(w.Requests);}
    [Fact]public void UnmappedScopeGuardDoesNotReinterpretLegacyOffers(){var w=Island(false);Assert.Equal(TaskKind.VoluntaryRequest,NewGameWorld.LocalWork(w,"request:legacy-island-offer").Kind);Assert.Null(w.WorkCycle);}
    static void ArmyInput(WorldSession s,NewMilitaryAction action,long amount=0){var result=s.DecideNewMilitary(new(new("request:army-pay/"+s.Revision),action,amount),s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);}
    [Fact]public void LaterDeploymentAtSameTimeCannotInvalidatePriorPayment(){var s=new WorldSession(New());Military(s);At(s,s.Seconds+2);foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);ArmyInput(s,NewMilitaryAction.Accept);At(s,s.Seconds+2);foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);ArmyInput(s,NewMilitaryAction.Pickup);ArmyInput(s,NewMilitaryAction.Load,100000);var t=Work(s);At(s,s.Seconds+6);Open(s);Assert.Equal(ResultCode.Accepted,Pay(s,t).Code);long at=s.Seconds;ArmyInput(s,NewMilitaryAction.Deploy);Assert.Equal(at,s.Seconds);Assert.Equal(1020,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));_ = new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));}
    [Fact]public void FailedReplyRetriesOnlyAfterAssessorLearnsFailure(){var s=new WorldSession(New());var t=Work(s);At(s,6);var note=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind==AssessmentNotice.Kind);s.DiagnosticTransport((mail,at)=>HakutaiKagami.Core.Messaging.MessageFlow.Fail(mail,note.Id));At(s,7);Assert.Single(s.DiagnosticSnapshot().Messaging.Attempts,a=>a.MessageId==note.Id);At(s,9);Assert.Equal(2,s.DiagnosticSnapshot().Messaging.Attempts.Count(a=>a.MessageId==note.Id));Open(s);Assert.Equal(ResultCode.Accepted,Pay(s,t).Code);Assert.Single(s.DiagnosticSnapshot().Transfers);}
    [Fact]public void ReturningToMeetingRestoresMissedReplyWithoutFollowingRemotePlayer(){var s=new WorldSession(New());var t=Work(s);At(s,5);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:before-reply","suwa"),s.Revision).Code);At(s,9);var notice=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind==AssessmentNotice.Kind);Assert.Single(s.DiagnosticSnapshot().Messaging.Attempts,a=>a.MessageId==notice.Id);Assert.Empty(AssessmentNotice.Inbox(s,s.PlayerControl));At(s,s.GetBranchView(s.PlayerControl).ArrivalAt!.Value+1);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:back-to-reply","kofu"),s.Revision).Code);At(s,s.Seconds+2);At(s,s.GetBranchView(s.PlayerControl).ArrivalAt!.Value+2);Assert.Single(AssessmentNotice.Inbox(s,s.PlayerControl));Assert.Equal(2,s.DiagnosticSnapshot().Messaging.Attempts.Count(a=>a.MessageId==notice.Id));Open(s);Assert.Equal(ResultCode.Accepted,Pay(s,t).Code);Assert.Equal(1020,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(5)][InlineData(6)][InlineData(7)][InlineData(8)]public void RestoreBeforeAndAfterPhysicalReplyAndPay(int at){var s=new WorldSession(New());EntityId? task=null;if(at>0)task=Work(s);At(s,at);if(at==8){Open(s);Pay(s,task!.Value);}s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"work-save-"+Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"manual",w.WorldId,new(0,1));var host=new WorldSessionHost(new(New()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));At(s,12);At(host.Current,12);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));}
}
